import java.time.LocalDate; public class Funcionario implements Autenticavel,Pagavel { private final String nome; private final double salario; private String senha; public Funcionario(String n,double s,String p){nome=n;salario=s;senha=p;} public boolean autenticar(String s){return senha.equals(s);} public void alterarSenha(String antiga,String nova){if(autenticar(antiga))senha=nova;} public double getValor(){return salario;} public String getDescricao(){return "Salário de "+nome;} public LocalDate getDataVencimento(){return LocalDate.now().withDayOfMonth(5).plusMonths(1);} }
